package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaUzDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("Birinchi mevani ko'rish", "Allohim, bizni mevamizga barakali qil, shahrimizga barakali, so'miz va muddimiz (o'lchovlarimiz)da barakali qil.", "Mavsumning birinchi mevasini ko'rishda.", "Rizqda va shaharda baraka uchun duo."),
        "dua_good_news" to DuaText("Quvonarli Yangilik ustiga", "Hamdu sanolar ne'mati bilan yaxshiliklarni tugatuvchi Allohgadir.", "Xushxabar olganingizda (va shukr sajdasini qilingiz).", "Payg'ambar ﷺ o'zlari yoqtirgan narsani ko'rib shunday dedilar."),
        "dua_looking_mirror" to DuaText("Oynaga qarash", "Allohim, tashqi koʻrinishimni goʻzal qilganingdek, xulqimni ham goʻzal qilgin.", "Oynaga qaraganingizda.", "Payg'ambar ﷺ bu duoni o'qigan (u ko'zguni eslatmasdan ham o'rnatilgan)."),
        "dua_rabbana_taqabbal" to DuaText("Amallarni qabul qilish", "Ey Robbimiz, buni bizdan qabul qil. Albatta, Sen eshitguvchi va bilguvchi zotsan. Va tavbalarimizni qabul qiling. Albatta, Sen tavbalarni qabul qiluvchi va rahmlisan.", "Ibrohim va Ismoil (AS) Ka'bani qurishda so'radilar.", "Har bir yaxshilikdan keyin qabul bo'ladigan duo."),
        "dua_muawwidhat" to DuaText("Uch Qul (Muavvidhat)", "(Ixlos surasi) Ayting: U Alloh yagonadir. Alloh o'zi bejizdir. U tug'ilmaydi va tug'ilmaydi. Va Unga teng keladigani yo'q.\n\n(Falaq surasi) Ayting: “Tongning Robbidan, U yaratgan narsaning yomonligidan, zulmat qo‘nayotgan paytda, tugunlarga puflovchilarning yomonligidan va hasad qilganida, hasad qiluvchining yomonligidan panoh so‘rayman.\n\n(Nos surasi) Ayting: «Men odamlarning Robbisi, odamlarning Podshohi, insonlarning ilohi, jin va insdan odamlarning qalbiga vasvasa qiluvchi, orqaga chekinuvchining yomonligidan panoh tilayman.", "Uch surani har kuni ertalab va kechqurun uch marta va uxlashdan oldin qo'llarga puflang va ularni tanaga surting.", "Ularni ertalab va kechqurun uch marta o'qish hamma narsaga kifoya qiladi."),
        "dua_sabr" to DuaText("Sabr va chidamlilik uchun", "Ey Robbimiz, ustimizga sabr ber, oyoqlarimizni mustahkam qil va kofir qavmga qarshi bizga nusrat ber.", "Qiyinchilik va qarama-qarshilik davrida.", "Tolut lashkarining duosi."),
        "dua_rabbana_innana_amanna" to DuaText("Kechirim va olovdan himoya qilish", "Ey Robbimiz, biz iymon keltirdik, gunohlarimizni mag‘firat qil va bizni do‘zax azobidan saqlagin.", "Qur'on duosi.", "Xudodan qo'rqqanlarning fazilatlari qatorida tilga olingan duo."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Ishimizdagi hidoyat (Ashab al-Kahf)", "Ey Robbimiz, bizga O'z huzuringdan rahmat ber va ishimizda to'g'ri hidoyat tayyorlagin.", "G'or ahlining duosi.", "Qarorlar va qiyin vaziyatlarda rahbarlik."),
        "dua_musa_faqir" to DuaText("Muso alayhissalomning duosi (AS)", "Parvardigorim, men senga nozil qilgan yaxshilikka muhtojman.", "Rizq va yaxshilikni izlash - Musoning duosi (AS) Madyanda.", "Bu duodan keyin Alloh Musoga (AS) uy, ish va xotin berdi."),
        "dua_ayyub" to DuaText("Ayyub alayhissalomning kasallikdagi duosi (AS)", "(Parvardigorim) menga zarar yetdi. Sen rahmlilarning rahmlisisan.", "Kasallik va azob-uqubatlarda.", "Alloh Ayyubning azobini ketkazdi (AS)."),
        "dua_husn_khatimah" to DuaText("Musulmon bo'lib o'ling (Yusuf alayhissalom)", "Osmonlaru yerning yaratuvchisi, Sen mening dunyo va oxiratdagi himoyachisisan. Meni musulmon holimda vafot et va meni solihlar qatoriga qo‘sh.", "Yaxshi yakun uchun duo.", "Yusuf payg'ambarning duosi (AS)."),
        "dua_shaitan_hamazat" to DuaText("Iblislarning shivirlashlaridan panoh", "Ey Robbim, shaytonlarning vasvasasidan Sendan panoh tilayman va ular menga yaqinlashib qolishlaridan panoh tilayman, Robbim.", "Shaytonning shivirlaridan panoh.", "Qur'onning boshpana izlash duosi."),
        "dua_bad_character" to DuaText("Yomon xarakterdan panoh", "Allohim, yomon xulqdan, yomon amallardan va yomon havaslardan panoh tilayman.", "Yomon xulq-atvor, amal va istaklardan panoh.", "Payg'ambardan panoh duosi ﷺ."),
        "dua_zawal_nimah" to DuaText("Ne'matlarni yo'qotishdan panoh", "Allohim, ne’matingni yo‘qotishdan, bergan saodatingni o‘zgartirishingdan, to‘satdan azobingdan va barcha g‘azabingdan panoh tilayman.", "Ne'matlarni yo'qotishdan va to'satdan keladigan ofatdan panoh.", "Payg'ambarning duosi ﷺ."),
        "dua_useless_knowledge" to DuaText("Foydasiz bilimlardan panoh", "Allohim, foyda bermaydigan ilmdan, qo'rqmaydigan qalbdan, to'ymaydigan qalbdan va ijobat bo'lmagan duodan panoh tilayman.", "Befoyda ilm va Allohdan qo'rqmagan qalbdan panoh.", "Payg'ambardan panoh duosi ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Foydali bilim va halol rizq", "Allohim, sendan foydali ilm, pok rizq va qabul qilingan amallarni so'rayman.", "Bomdod namozidan keyin.", "Rasululloh ﷺ bomdod salomlaridan keyin aytdilar."),
        "dua_leprosy_diseases" to DuaText("Jiddiy kasalliklardan boshpana", "Allohim, vitiligo, jinnilik, moxov va barcha yomon kasalliklardan Sendan panoh tilayman.", "Jiddiy kasalliklardan himoya qilish.", "Salomatlikni saqlash uchun sunnat duo."),
        "dua_fear_people" to DuaText("Dushmanlar yoki zolimlardan qo'rqish", "Allohim, Seni ularning oldiga qo'yamiz va Sendan ularning yomonligidan panoh tilaymiz.", "Bir kishining yoki bir kishining zararidan qo'rqqaningizda.", "Payg'ambar ﷺ bir qavmdan qo'rqqanlarida shunday dedilar."),
        "dua_shirk_protection" to DuaText("Yashirin shirkdan himoya", "Allohim, senga bilib turib biror narsani sherik qilishdan panoh tilayman va bilmay qilgan amallarim uchun Sendan magfirat so‘rayman.", "O'zini ko'rsatishdan va yashirin shirkdan omon qolish uchun.", "Yashirin shirk chumolining sudralishidan ko'ra yashirinroqdir."),
        "dua_rain" to DuaText("Yomg'ir Yog'ganda", "Allohim, foydali yomg'ir yog'dir.", "Yomg'ir yog'ayotganda.", "Yomg'ir - duolar qabul qilinadigan vaqt."),
        "dua_after_rain" to DuaText("Yomg'irdan keyin", "Bizga Allohning fazli va rahmati ila yomg'ir berildi.", "Yomg'irdan keyin.", "Bu gapni aytgan kishi Allohga mo'min bo'ladi."),
        "dua_istisqa" to DuaText("Yomg'ir so'rash (Istisqa)", "Allohim, bizga yomg'ir yuborgin (uch marta).", "Yomg'ir bo'lmaganda.", "Payg'ambarimiz ﷺ juma xutbalarida shu duoni o'qidilar va yomg'ir yog'di."),
        "dua_heavy_rain" to DuaText("Haddan tashqari yomg'ir", "Allohim, (uni o'zimizga emas, atrofimizga tushsin).", "Yomg'ir juda ko'p bo'lganda.", "Payg'ambarning duolari orqali bulutlar uzoqlashdi ﷺ."),
        "dua_wind" to DuaText("Shamol esganda", "Allohim, men Sendan uning yaxshiligini, ichidagi yaxshiligini va u bilan yuborilgan narsaning yaxshiligini so'rayman va uning yomonligidan, ichidagi yomonligidan va u bilan yuborilgan narsaning yomonligidan panoh tilayman.", "Kuchli shamol yoki bo'ron esganda.", "Payg'ambar ﷺ bo'ron paytida bu duoni qilgan."),
        "dua_thunder" to DuaText("Momaqaldiroqni eshitish", "Momaqaldiroq va farishtalar Undan qo'rqib tasbih aytadigan zot pokdir.", "Momaqaldiroqni eshitish haqida — Abdulloh ibn az-Zubayr amaliyoti (RA).", "Ra'd surasidan olingan (13:13)."),
        "dua_new_moon" to DuaText("Yangi oyni ko'rish", "Allohim, bu oy ustimizdan baraka, iymon, omonlik va islom bilan chiqsin. (Ey oy) mening Robbim va sizning Robbingiz Allohdir.", "Yangi oyni ko'rishda.", "Har bir yangi oy uchun sunnat duosi."),
        "dua_janaza_adult" to DuaText("Janaza namozi (kattalar)", "Allohim, tiriklarimizni va o'liklarimizni, hozir bo'lganlarimizni va yo'qlarimizni, yoshu qarilarimizni, erkaklarimizni va ayollarimizni mag'firat qil. Allohim, bizdan kimni tirik tutsang, uni Islomda saqlagin, kimni o'ldirsang, uni iymon bilan o'ldirgin.", "Janoza namozining uchinchi takbiridan keyin.", "Voyaga yetgan marhum uchun sunnat duosi."),
        "dua_janaza_child" to DuaText("Janaza namozi (bola)", "Allohim, uni bizlar uchun oldingi (va mezbon) qil, uni bizga mukofot va xazina qil va shafoati qabul qilingan shafoatchi qil.", "Bolaning janoza namozida (qiz bolaga \"ij'alha\" deng).", "Hanafiylar qilgan sunnat duo."),
        "dua_mayyit_awf" to DuaText("Marhum uchun batafsil duo", "Allohim, uni mag‘firat et, rahm qil, unga sog‘lik ber va kechir. Uning ziyofatini sharafli, qabrini keng qil, uni suv, qor va do‘l bilan yuv, oq kiyim kirdan tozalanganidek, gunohlardan poklagin.", "Janoza namozida yoki marhum uchun.", "Avf ibn Molik (RA) o'sha marhum bo'lishini orzu qilgan."),
        "dua_visiting_graves" to DuaText("Qabrlarni ziyorat qilish", "Assalomu alaykum, ey bu xonadonlarning mo‘min va musulmon ahli. Biz ham, agar Alloh xohlasa, sizga qo'shilamiz. Allohdan bizga ham, sizlarga ham omonlik tilayman.", "Qabristonga kirayotganda.", "Qabrlarni ziyorat qilish o‘lim va oxiratni eslatadi."),
        "dua_closing_eyes" to DuaText("Marhumning ko'zlarini yumgandan keyin", "Allohim, mag'firat qil (ismini), hidoyat topganlar qatorida uning darajasini ko'tar, qoldirganlar orasida uning o'rinbosar bo'l. Bizni ham, uni ham mag‘firat qil, ey olamlarning Robbi! qabrini keng qilib, nurga to'ldirgin.", "Marhumning ko'zlarini yumganda (uning ismini aytib).", "Rasululloh ﷺ Abu Salamaga (RA) duo qilganlar."),
        "dua_condolence" to DuaText("Ta’ziya (Ta’ziya)", "Albatta, Allohning olgani va bergani Unikidir va har bir narsaning Uning huzurida belgilangan muddat bor.", "O'limdan keyin oila a'zolariga hamdardlik bildirish.", "Payg'ambar ﷺ bu xabarni qiziga yubordi."),
        "dua_placing_in_grave" to DuaText("Marhumni qabrga qo'yish", "Alloh nomi bilan va Rasululloh yo'lida ﷺ.", "Marhumni qabrga tushirganda.", "Dafn qilishning sunnat duosi."),
        "dua_sneezing" to DuaText("Hapşırma", "Hamma hamdlar Allohgadir. — Alloh rahmatiga olsin. — Alloh sizni hidoyat qilsin, ishlaringizni isloh qilsin.", "Hapşırmada; tinglovchi “Yarhamukalloh” desa, aksirgan kishi javob beradi.", "Musulmonning boshqa bir musulmonga nisbatan haqlaridan biridir."),
        "dua_toilet_enter" to DuaText("Tualetga kirish", "Alloh nomi bilan. Allohim, sendan harom jinlar erkak va ayoldan panoh tilayman.", "Chap oyoq bilan hojatxonaga kirishdan oldin.", "Bismilloh jin va odam o'rtasidagi pardaga aylanadi."),
        "dua_toilet_exit" to DuaText("Hojatxonadan chiqish", "(Allohim) Sendan mag'firat so'rayman.", "O'ng oyoq bilan hojatxonadan chiqayotganda.", "Payg'ambarimiz ﷺ buni hojatxonadan chiqayotganlarida aytdilar."),
        "dua_thanking" to DuaText("Kimgadir rahmat", "Alloh sizni yaxshilik bilan mukofotlasin.", "Kimdir sizga yaxshilik qilsa.", "Kim buni aytsa, to'liq minnatdorchilik bildirgan."),
        "dua_love_for_allah" to DuaText("Kimdir \"Men seni Alloh uchun sevaman\" desa", "Meni kim uchun yaxshi ko'rsangiz, sizni ham sevsin.", "Kimdir \"Men seni Alloh uchun yaxshi ko'raman\" desa.", "Sunnat Alloh uchun muhabbatga javob beradi."),
        "dua_seeing_muslim_smile" to DuaText("Assalomu alaykum", "Assalomu alaykum va Allohning rahmati va barakotlari.", "Musulmon bilan uchrashganda.", "To'liq salom aytish o'ttizta yaxshilikka erishadi."),
        "dua_dressing" to DuaText("Kiyinish", "Buni menga kiyintirgan va mendan hech qanday kuch va kuchsiz rizqlagan Allohga hamdlar bo'lsin.", "Kiyinayotganda.", "O'tgan gunohlar kechirilishining xushxabari."),
    )
}
